import{_ as a,o,c as r,a0 as s}from"./chunks/framework.DCluYYrN.js";const p=JSON.parse('{"title":"O que é KernelSU?","description":"","frontmatter":{},"headers":[],"relativePath":"pt_BR/guide/what-is-kernelsu.md","filePath":"pt_BR/guide/what-is-kernelsu.md"}'),t={name:"pt_BR/guide/what-is-kernelsu.md"};function n(l,e,i,u,c,m){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="o-que-e-kernelsu" tabindex="-1">O que é KernelSU? <a class="header-anchor" href="#o-que-e-kernelsu" aria-label="Permalink to &quot;O que é KernelSU?&quot;">​</a></h1><p>O KernelSU é uma solução root para dispositivos Android GKI, funciona no modo kernel e concede privilégios root para apps do espaço do usuário diretamente no espaço do kernel.</p><h2 id="caracteristicas" tabindex="-1">Características <a class="header-anchor" href="#caracteristicas" aria-label="Permalink to &quot;Características&quot;">​</a></h2><p>A principal característica do KernelSU é que ele é <strong>baseado em kernel</strong>. O KernelSU funciona no modo kernel, portanto pode fornecer uma interface de kernel que nunca tivemos antes. Por exemplo, é possível adicionar pontos de interrupção de hardware a qualquer processo no modo kernel, acessar a memória física de qualquer processo de forma invisível, interceptar qualquer chamada de sistema (syscall) no espaço do kernel, entre outras funcionalidades.</p><p>Além disso, o KernelSU fornece um <a href="./metamodule.html">sistema metamodule</a>, que é uma arquitetura plugável para gerenciamento de módulos. Diferente das soluções root tradicionais que integram a lógica de montagem em seu núcleo, o KernelSU delega isso aos metamodules. Isso permite que você instale metamodules como <a href="https://github.com/tiann/KernelSU/tree/main/userspace/meta-overlayfs" target="_blank" rel="noreferrer">meta-overlayfs</a> para fornecer modificações systemless na partição <code>/system</code> e outras partições.</p><h2 id="como-usar-o-kernelsu" tabindex="-1">Como usar o KernelSU? <a class="header-anchor" href="#como-usar-o-kernelsu" aria-label="Permalink to &quot;Como usar o KernelSU?&quot;">​</a></h2><p>Por favor, consulte: <a href="./installation.html">Instalação</a></p><h2 id="como-compilar-o-kernelsu" tabindex="-1">Como compilar o KernelSU? <a class="header-anchor" href="#como-compilar-o-kernelsu" aria-label="Permalink to &quot;Como compilar o KernelSU?&quot;">​</a></h2><p>Por favor, consulte: <a href="./how-to-build.html">Como compilar</a></p><h2 id="discussao" tabindex="-1">Discussão <a class="header-anchor" href="#discussao" aria-label="Permalink to &quot;Discussão&quot;">​</a></h2><ul><li>Telegram: <a href="https://t.me/KernelSU" target="_blank" rel="noreferrer">@KernelSU</a></li></ul>',11)])])}const h=a(t,[["render",n]]);export{p as __pageData,h as default};
